function act(obs, mem) {
  if (!mem.init) {
    mem.init = 1;
    mem.px = obs.x;
    mem.py = obs.y;
    mem.stuck = 0;
    mem.tgtIdx = obs.targetIndex;
    mem.revCount = 0;
    mem.revDir = 1;
  }
  if (obs.targetIndex !== mem.tgtIdx) {
    mem.stuck = 0;
    mem.tgtIdx = obs.targetIndex;
  }

  const dx = obs.targetX - obs.x,
        dy = obs.targetY - obs.y,
        dist = Math.sqrt(dx * dx + dy * dy),
        hR = obs.heading * Math.PI / 180;
  let ang = Math.atan2(dy, dx) - hR;
  while (ang > Math.PI) ang -= 2 * Math.PI;
  while (ang < -Math.PI) ang += 2 * Math.PI;

  const r = obs.rays,
        rA = [-Math.PI/3, -Math.PI/6, 0, Math.PI/6, Math.PI/3];

  // Potential field: repulsive from obstacles
  let rpX = 0, rpY = 0;
  const SAFE = 5;
  for (let i = 0; i < 5; i++) {
    const d = Math.min(r[i], 10);
    if (d < SAFE && d > 0.01) {
      const t = (SAFE - d) / SAFE;
      const w = t * t * 3;
      rpX -= Math.cos(rA[i]) * w;
      rpY -= Math.sin(rA[i]) * w;
    }
  }

  // Narrow gap heuristic: corridor visible ahead, walls on both sides
  if (r[2] > 7 && r[1] < 3 && r[3] < 3) {
    rpX *= 0.5;
    rpY *= 0.5;
  }

  // Attractive toward target
  const aW = Math.max(0.4, Math.min(1, dist / 3));
  const cX = Math.cos(ang) * aW + rpX;
  const cY = Math.sin(ang) * aW + rpY;
  let steer = (cX * cX + cY * cY > 0.003) ? Math.atan2(cY, cX) : ang;

  // Speed control
  const minR = Math.min(r[0], r[1], r[2], r[3], r[4]);
  let spd = 1.0;
  const aSt = Math.abs(steer);
  if (aSt > 0.7) spd = 0.8;
  if (aSt > 1.2) spd = 0.5;
  if (aSt > 1.7) spd = 0.25;
  if (r[2] < 4)   spd = Math.min(spd, 0.8);
  if (r[2] < 2)   spd = Math.min(spd, 0.5);
  if (r[2] < 1.2) spd = Math.min(spd, 0.15);
  if (minR < 1.5) spd = Math.min(spd, 0.25);
  if (minR < 0.8) spd = Math.min(spd, 0.1);
  if (dist < 2)   spd = Math.min(spd, 0.5);
  if (dist < 1)   spd = Math.min(spd, 0.25);

  // Emergency avoidance
  if (minR < 0.5) {
    let bestI = 0, bestD = r[0];
    for (let i = 1; i < 5; i++) {
      if (r[i] > bestD) { bestD = r[i]; bestI = i; }
    }
    steer = rA[bestI] * 1.5;
    spd = 0.05;
  } else if (r[2] < 1.0) {
    const lo = r[0] + r[1], ro = r[3] + r[4];
    steer = lo > ro ? -1.5 : 1.5;
    spd = Math.min(spd, 0.12);
  }

  // Motor commands (differential drive)
  let left = spd - steer * 0.85;
  let right = spd + steer * 0.85;
  left = Math.max(-1, Math.min(1, left));
  right = Math.max(-1, Math.min(1, right));

  // Stuck detection via GPS movement
  const mv = Math.sqrt(
    (obs.x - mem.px) * (obs.x - mem.px) +
    (obs.y - mem.py) * (obs.y - mem.py)
  );
  if (mv < 0.02 && obs.t > 1) {
    mem.stuck++;
  } else {
    mem.stuck = Math.max(0, mem.stuck - 2);
  }
  mem.px = obs.x;
  mem.py = obs.y;

  // Stuck recovery: reverse with alternating turn
  if (mem.stuck > 25) {
    mem.revCount++;
    left = -0.5 + 0.3 * mem.revDir;
    right = -0.5 - 0.3 * mem.revDir;
    if (mem.revCount > 12) {
      mem.stuck = 0;
      mem.revCount = 0;
      mem.revDir *= -1;
    }
  }

  return { left, right };
}

