    mem.lastTargetIndex = -9999;
    mem.lastTx = undefined;
    mem.lastTy = undefined;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.lastDrive = 0;
    mem.lastTurnCmd = 0;
