        const nid = ny * GW + nx;
        if (closed[nid]) continue;

        const o = mem.occ[nid];
        if (o >= blockThresh && nid !== goal) continue;

        const wx = OX + (nx + 0.5) * CELL;
        const wy = OY + (ny + 0.5) * CELL;
