            }
          }
        }
        extra += near * 0.018;

        const dEdge = Math.min(wx, 40 - wx, wy, 40 - wy);
        if (dEdge < 1.0) extra += (1.0 - dEdge) * 1.2;

        const ng = cg + base * (1 + extra);
        if (ng < gs[nid] - 1e-7) {
