        const ix = id % GW;
        const iy = (id - ix) / GW;
        const wx = OX + (ix + 0.5) * CELL;
        const wy = OY + (iy + 0.5) * CELL;
        const d = Math.hypot(wx - x, wy - y);
        if (d > 0.28) {
          fallback = [wx, wy];
          if (d >= look) {
            chosen = [wx, wy];
            chosenD = d;
            break;
          }
        }
      }

      if (!chosen && fallback) {
        chosen = fallback;
        chosenD = Math.hypot(chosen[0] - x, chosen[1] - y);
      }

      if (chosen && chosenD > 0.9 &&
          !lineClear(x, y, chosen[0], chosen[1], 3)) {
        let safe = null;
        for (let k = 0; k < mem.path.length; k++) {
          const id = mem.path[k];
          const ix = id % GW;
          const iy = (id - ix) / GW;
          const wx = OX + (ix + 0.5) * CELL;
          const wy = OY + (iy + 0.5) * CELL;
          const d = Math.hypot(wx - x, wy - y);
          if (d > 0.28 && d <= chosenD + 0.01) {
