      desiredY = ty;
    }

    let desiredHeading = Math.atan2(desiredY - y, desiredX - x);
    if (!isFinite(desiredHeading)) desiredHeading = heading;
    let err = wrap(desiredHeading - heading);
    const absErr = Math.abs(err);

    const front = rays[2];
    let avoid = 0;

    for (let i = 0; i < 5; i++) {
      if (i === 2) continue;
      const d = rays[i];
      const rel = RAY_ANG[i];
      const safeSide = (i === 1 || i === 3) ? 0.95 : 0.80;
      if (d < safeSide) {
        let c = (safeSide - d) / safeSide;
        if (c > 1) c = 1;
