    if ((rays[0] < 0.30 || rays[1] < 0.34) &&
        rays[3] > 0.55 && rays[4] > 0.55) {
      avoid += 0.55;
    }
    if ((rays[3] < 0.30 || rays[4] < 0.34) &&
        rays[0] > 0.55 && rays[1] > 0.55) {
      avoid -= 0.55;
    }

    avoid = clamp(avoid, -1.4, 1.4);
    mem.avoidFilter = (Number(mem.avoidFilter) || 0) * 0.55 + avoid * 0.45;
    let steerAvoid = Number(mem.avoidFilter) || 0;
    if (front < 0.58) steerAvoid = avoid;

    let turn = 1.12 * err - 0.40 * yaw + 0.95 * steerAvoid;

    let align = Math.cos(err);
    if (align < 0) align = 0;
    let desiredV = 1.02 * align;

