}

function act(obs, mem) {
  const RAD = Math.PI / 180;
  const CELL = 0.4, OX = -2, OY = -2, GW = 112, GH = 112, MAPN = GW * GH;
  const RAY_ANG = [-60 * RAD, -30 * RAD, 0, 30 * RAD, 60 * RAD];

  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
  function wrap(a) {
    while (a > Math.PI) a -= 2 * Math.PI;
    while (a < -Math.PI) a += 2 * Math.PI;
    return a;
  }

  if (!mem || typeof mem !== "object") mem = {};

  const now = Number(obs.t) || 0;
  const x = Number(obs.x) || 0;
  const y = Number(obs.y) || 0;
  const hRaw = wrap((Number(obs.heading) || 0) * RAD);
  const rawSpeed = Number(obs.speed) || 0;
  const speed = Math.abs(rawSpeed);

  const restart = !mem.init || now < (Number(mem.lastT) || 0) - 1e-6;

  if (restart) {
    mem.init = true;
    mem.lastT = now;
    mem.lastX = x;
    mem.lastY = y;
    mem.lastRawHeading = undefined;
    mem.yawFilter = 0;
    mem.headOffset = 0;
    mem.offCount = 0;
    mem.cal = null;
    mem.badCal = 0;
    mem.resetMap = false;
    mem.bias = 0;
    mem.occ = new Int16Array(MAPN);
    mem._g = new Float32Array(MAPN);
    mem._came = new Int32Array(MAPN);
    mem._closed = new Uint8Array(MAPN);
    mem.path = null;
    mem.planT = -1e9;
    mem.lastTargetIndex = -9999;
    mem.lastTx = undefined;
    mem.lastTy = undefined;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.lastDrive = 0;
    mem.lastTurnCmd = 0;
    mem.stuck = 0;
    mem.blocked = 0;
    mem.recoverUntil = -1e9;
    mem.recoverBackUntil = -1e9;
    mem.recoverSide = 1;
    mem.lastRecoverSide = 0;
    mem.avoidFilter = 0;
    mem.avoidSide = 1;
  }

  if (!mem.occ || mem.occ.length !== MAPN) {
    mem.occ = new Int16Array(MAPN);
    mem._g = new Float32Array(MAPN);
    mem._came = new Int32Array(MAPN);
    mem._closed = new Uint8Array(MAPN);
    mem.path = null;
    mem.planT = -1e9;
  }

  const dtRaw = now - (Number(mem.lastT) || now);
  const dt = dtRaw > 0 ? Math.min(0.25, dtRaw) : 0.05;

  let dhRaw = 0;
  if (mem.lastRawHeading !== undefined) dhRaw = wrap(hRaw - mem.lastRawHeading);
  let yawMeas = dt > 0 ? dhRaw / dt : 0;
  yawMeas = clamp(yawMeas, -8, 8);
  mem.yawFilter = (Number(mem.yawFilter) || 0) * 0.72 + yawMeas * 0.28;
  if (!isFinite(mem.yawFilter)) mem.yawFilter = 0;

  const rawRays = obs.rays || [];
  const rays = [10, 10, 10, 10, 10];
  for (let i = 0; i < 5; i++) {
    let r = Number(rawRays[i]);
    if (!isFinite(r)) r = 10;
    if (r < 0.05) r = 0.05;
    if (r > 10) r = 10;
    rays[i] = r;
