  const lastTurn = Number(mem.lastTurnCmd) || 0;

  // Calibrate compass offset using mostly-straight forward motion.
  if (speed > 0.10 && lastDrive > 0.08 && Math.abs(lastTurn) < 0.25) {
    if (!mem.cal) {
      mem.cal = { x: x, y: y, t: now, raw: hRaw };
    } else {
      const cdt = now - mem.cal.t;
      const cdx = x - mem.cal.x;
      const cdy = y - mem.cal.y;
      const cdist = Math.hypot(cdx, cdy);
      const dh = wrap(hRaw - mem.cal.raw);

      if (cdt > 1.25 || Math.abs(dh) > 0.55 || cdist > 2.2) {
