      } else if (cdt >= 0.45 && cdist > 0.16 && Math.abs(dh) < 0.40) {
        const avgRaw = wrap(mem.cal.raw + dh * 0.5);
        const measured = Math.atan2(cdy, cdx);
        const cand = wrap(measured - avgRaw);
        const off = wrap(Number(mem.headOffset) || 0);
        const delta = wrap(cand - off);
        const count = Number(mem.offCount) || 0;

        if (count === 0) {
          if (cdist > 0.32 || cdt > 0.68) {
            mem.headOffset = cand;
            mem.offCount = 1;
            if (Math.abs(cand) > 0.12) mem.resetMap = true;
          }
        } else if (Math.abs(delta) < 0.80) {
          const alpha = count < 4 ? 0.16 : 0.045;
          const step = delta * alpha;
          mem.headOffset = wrap(off + step);
          if (Math.abs(step) > 0.24) mem.resetMap = true;
          mem.offCount = count + 1;
          mem.badCal = 0;
        } else {
          mem.badCal = (Number(mem.badCal) || 0) + 1;
          if (mem.badCal >= 6) {
            mem.headOffset = cand;
            mem.offCount = count + 1;
            mem.resetMap = true;
            mem.badCal = 0;
          }
        }
        mem.cal = { x: x, y: y, t: now, raw: hRaw };
      }
    }
  } else {
    mem.cal = { x: x, y: y, t: now, raw: hRaw };
  }

  if (mem.resetMap) {
    mem.occ.fill(0);
    mem.path = null;
    mem.planT = -1e9;
    mem.resetMap = false;
  }

  const heading = wrap(hRaw + (Number(mem.headOffset) || 0));
  const occ = mem.occ;

  function markIdx(ix, iy, d) {
    if (ix < 0 || ix >= GW || iy < 0 || iy >= GH) return;
    const id = iy * GW + ix;
    let v = occ[id] + d;
    if (v > 30) v = 30;
    if (v < -30) v = -30;
    occ[id] = v;
  }
  function markWorld(wx, wy, d) {
    const ix = Math.floor((wx - OX) / CELL);
    const iy = Math.floor((wy - OY) / CELL);
    markIdx(ix, iy, d);
  }
  function occAtWorld(wx, wy) {
    const ix = Math.floor((wx - OX) / CELL);
    const iy = Math.floor((wy - OY) / CELL);
    if (ix < 0 || ix >= GW || iy < 0 || iy >= GH) return 30;
    return occ[iy * GW + ix];
  }
  function lineClear(x0, y0, x1, y1, thr) {
    const dx = x1 - x0, dy = y1 - y0;
    const dist = Math.hypot(dx, dy);
    if (dist < 0.05) return true;
    const n = Math.max(1, Math.ceil(dist / 0.22));
    for (let s = 1; s < n; s++) {
      const tt = s / n;
      const wx = x0 + dx * tt;
      const wy = y0 + dy * tt;
      const ix = Math.floor((wx - OX) / CELL);
      const iy = Math.floor((wy - OY) / CELL);
      if (ix < 0 || ix >= GW || iy < 0 || iy >= GH) return false;
      if (occ[iy * GW + ix] >= thr) return false;
    }
    return true;
  }

  markWorld(x, y, -4);

  for (let i = 0; i < 5; i++) {
    const r = rays[i];
    const ang = heading + RAY_ANG[i];
    const ca = Math.cos(ang), sa = Math.sin(ang);
    const hit = r < 9.55;
    const freeMax = hit ? Math.max(0.0, r - 0.18) : Math.min(r, 8.6);

    for (let d = 0.22; d < freeMax; d += 0.30) {
      markWorld(x + ca * d, y + sa * d, -1);
    }

    if (hit) {
      const ex = x + ca * r;
      const ey = y + sa * r;
      const ix = Math.floor((ex - OX) / CELL);
      const iy = Math.floor((ey - OY) / CELL);
      markIdx(ix, iy, 6);
      for (let ax = -1; ax <= 1; ax++) {
        for (let ay = -1; ay <= 1; ay++) {
          if (ax !== 0 || ay !== 0) markIdx(ix + ax, iy + ay, 1);
        }
      }
    }
  }

  let tx = Number(obs.targetX), ty = Number(obs.targetY);
  if (!isFinite(tx) || !isFinite(ty)) {
    const arr = obs.targets || [];
    const ti = Math.max(0, Number(obs.targetIndex) || 0);
    const p = arr[ti];
    if (Array.isArray(p)) {
      tx = Number(p[0]);
      ty = Number(p[1]);
    } else if (p) {
      tx = Number(p.x);
      ty = Number(p.y);
    }
  }
  if (!isFinite(tx) || !isFinite(ty)) {
    tx = x + Math.cos(heading) * 2;
    ty = y + Math.sin(heading) * 2;
  }

  const targetIndex = (obs.targetIndex === undefined) ? 0 : Number(obs.targetIndex);
  const targetChanged = mem.lastTargetIndex !== targetIndex ||
    (mem.lastTx !== undefined && Math.hypot(tx - mem.lastTx, ty - mem.lastTy) > 1.0);
  if (targetChanged) {
    mem.path = null;
    mem.planT = -1e9;
  }

  let inRecovery = now < (Number(mem.recoverUntil) || -1e9);

  if (!inRecovery) {
    if (Math.abs(lastDrive) > 0.18 && speed < 0.035) {
      mem.stuck = (Number(mem.stuck) || 0) + dt;
    } else {
      mem.stuck = Math.max(0, (Number(mem.stuck) || 0) - dt * 1.8);
    }

    if (rays[2] < 0.50 && Math.abs(lastDrive) > 0.08 && speed < 0.10) {
      mem.blocked = (Number(mem.blocked) || 0) + dt;
    } else {
      mem.blocked = Math.max(0, (Number(mem.blocked) || 0) - dt * 1.6);
    }

    if ((Number(mem.stuck) || 0) > 1.15 ||
        (Number(mem.blocked) || 0) > 0.62 ||
        (rays[2] < 0.27 && speed < 0.06)) {
      const lc = Math.min(rays[3], rays[4]);
      const rc = Math.min(rays[1], rays[0]);
      let side = lc >= rc ? 1 : -1;
      if (Math.abs(lc - rc) < 0.10) {
        side = -(Number(mem.lastRecoverSide) || 1);
        if (!side) side = 1;
      }

      mem.recoverSide = side;
      mem.lastRecoverSide = side;

      const behindX = x - Math.cos(heading) * 0.55;
      const behindY = y - Math.sin(heading) * 0.55;
      const behindOcc = occAtWorld(behindX, behindY);
      mem.recoverBackUntil = (rays[2] < 0.38 && behindOcc < 8)
        ? now + 0.18
        : now - 1;

      mem.recoverUntil = now + 0.75;
      mem.stuck = 0;
      mem.blocked = 0;
      mem.path = null;
      mem.planT = now + 0.75;
      inRecovery = true;
