        bestId = cur;
      }

      const cg = gs[cur];

      for (let di = 0; di < 8; di++) {
        const dx = dirs[di][0], dy = dirs[di][1], base = dirs[di][2];
        const nx = cx + dx, ny = cy + dy;
        if (nx < 0 || nx >= GW || ny < 0 || ny >= GH) continue;
        const nid = ny * GW + nx;
        if (closed[nid]) continue;

        const o = occ[nid];
        if (o >= blockTh && nid !== goal) continue;

        const wx = OX + (nx + 0.5) * CELL;
        const wy = OY + (ny + 0.5) * CELL;
        if (nid !== goal &&
            (wx < 0.48 || wx > 39.52 || wy < 0.48 || wy > 39.52)) {
          continue;
        }

        if (dx !== 0 && dy !== 0) {
          const a = cy * GW + (cx + dx);
          const b = (cy + dy) * GW + cx;
          if (occ[a] >= blockTh && a !== goal) continue;
          if (occ[b] >= blockTh && b !== goal) continue;
        }

        let extra = 0;
        if (o > 0) extra += o * 0.09;

        let near = 0;
        for (let ax = -1; ax <= 1; ax++) {
          for (let ay = -1; ay <= 1; ay++) {
            const xx = nx + ax, yy = ny + ay;
            if (xx >= 0 && xx < GW && yy >= 0 && yy < GH) {
              const oo = occ[yy * GW + xx];
              if (oo > 0) near += Math.min(oo, 20);
            }
          }
        }
        extra += near * 0.010;

        const dEdge = Math.min(wx, 40 - wx, wy, 40 - wy);
        if (dEdge < 0.85) extra += (0.85 - dEdge) * 1.5;

        const ng = cg + base * (1 + extra);
        if (ng < gs[nid] - 1e-7) {
          gs[nid] = ng;
          came[nid] = cur;
          hpush(nid, ng + Math.hypot(nx - gix, ny - giy));
        }
      }
    }

    if (!reached && bestId === start) return null;

    const targetNode = reached ? goal : bestId;
    const rev = [];
    let cur = targetNode;
    let guard = 0;

    while (cur !== -1 && guard++ < MAPN) {
      rev.push(cur);
      if (cur === start) break;
      cur = came[cur];
    }
    if (rev[rev.length - 1] !== start) return null;
    rev.reverse();
    return rev;
  }

  let inRecovery = now < (Number(mem.recoverUntil) || -1e9);

  if (!inRecovery) {
    const moved = Math.hypot(x - (Number(mem.progX) || x), y - (Number(mem.progY) || y));
    if (moved > 0.55 || distT < 1.15) {
      mem.progT = now;
      mem.progX = x;
      mem.progY = y;
    }

    if (lastDrive > 0.14 && Math.abs(lastTurn) < 0.24 && speed < 0.040) {
      mem.stuck = (Number(mem.stuck) || 0) + dt;
    } else {
      mem.stuck = Math.max(0, (Number(mem.stuck) || 0) - dt * 1.7);
    }

    if (rays[2] < 0.55 && lastDrive > 0.07 && speed < 0.09) {
      mem.blocked = (Number(mem.blocked) || 0) + dt;
    } else {
      mem.blocked = Math.max(0, (Number(mem.blocked) || 0) - dt * 1.6);
    }

    const stalled = (now - (Number(mem.progT) || now) > 3.4) &&
                    distT > 1.45 &&
                    speed < 0.60;

    if ((Number(mem.stuck) || 0) > 1.35 ||
        (Number(mem.blocked) || 0) > 0.95 ||
        stalled ||
        (rays[2] < 0.25 && speed < 0.05 && (Number(mem.blocked) || 0) > 0.40)) {
      const lc = Math.min(rays[3], rays[4]);
      const rc = Math.min(rays[1], rays[0]);
      let side = lc >= rc ? 1 : -1;

      if (Math.abs(lc - rc) < 0.13) {
        const rough = wrap(Math.atan2(ty - y, tx - x) - heading);
        if (Math.abs(rough) > 0.15) side = rough > 0 ? 1 : -1;
        else side = -(Number(mem.lastRecoverSide) || 1);
      }
      if (!side) side = 1;

      mem.recoverSide = side;
      mem.lastRecoverSide = side;

      const behindX = x - Math.cos(heading) * 0.50;
      const behindY = y - Math.sin(heading) * 0.50;
      const behindOcc = occAtWorld(behindX, behindY);
      const canBack = behindOcc < 6 || (rays[2] < 0.30 && behindOcc < 12);

      mem.recoverBackUntil = canBack ? now + 0.28 : now - 1;
      mem.recoverUntil = now + 0.95;
      mem.stuck = 0;
      mem.blocked = 0;
      mem.path = null;
      mem.planT = now + 0.95;
      mem.progT = now;
      mem.progX = x;
      mem.progY = y;
      inRecovery = true;
    }
  }

  if (!inRecovery) {
    let needPlan = now >= (Number(mem.planT) || -1e9) ||
                   !mem.path ||
                   mem.pathTargetIndex !== targetIndex;

    if (!needPlan && mem.path) {
      const lim = Math.min(mem.path.length, 6);
      for (let k = 0; k < lim; k++) {
        const id = mem.path[k];
        if (occ[id] >= 10) {
          needPlan = true;
          break;
        }
      }
    }

    if (needPlan) {
      let p = null;
      const thresholds = [5, 8, 14, 25];
      for (let k = 0; k < thresholds.length; k++) {
        const q = planPath(tx, ty, thresholds[k]);
        if (q && q.length > 1) {
          p = q;
          break;
        }
      }
      mem.path = p;
      mem.pathTargetIndex = targetIndex;
      mem.planT = now + (p ? 0.90 : 0.30);
    }
  }

  let left = 0, right = 0;
  let maxStep = 0.12;

  if (inRecovery) {
    maxStep = 0.20;
    if (now < (Number(mem.recoverBackUntil) || -1e9)) {
      left = -0.18;
      right = -0.18;
    } else {
      const side = Number(mem.recoverSide) || 1;
      const u = 0.25;
      left = -u * side;
      right = u * side;
    }
  } else {
    let desiredX = tx;
    let desiredY = ty;
    const path = mem.path;

    if (path && path.length > 1) {
      let bi = 0, bd2 = 1e18;

      for (let k = 0; k < path.length; k++) {
        const id = path[k];
        const ix = id % GW;
        const iy = (id - ix) / GW;
        const wx = OX + (ix + 0.5) * CELL;
        const wy = OY + (iy + 0.5) * CELL;
        const dx = wx - x, dy = wy - y;
        const d2 = dx * dx + dy * dy;
        if (d2 < bd2) {
          bd2 = d2;
          bi = k;
        }
      }

      const lookMax = 1.00 + 0.55 * Math.min(speed, 1.5);
      let prevX = 0, prevY = 0;
      let acc = 0;
      let chosenX = null, chosenY = null;

      for (let k = bi; k < path.length; k++) {
        const id = path[k];
        const ix = id % GW;
        const iy = (id - ix) / GW;
        const wx = OX + (ix + 0.5) * CELL;
        const wy = OY + (iy + 0.5) * CELL;

        if (k === bi) {
          prevX = wx;
          prevY = wy;
        } else {
          const seg = Math.hypot(wx - prevX, wy - prevY);
          acc += seg;
          if (acc > lookMax) break;

          if (lineClear(x, y, wx, wy, 4)) {
            chosenX = wx;
            chosenY = wy;
          }
          prevX = wx;
          prevY = wy;
        }
      }

      if (chosenX === null) {
        const k = Math.min(path.length - 1, bi + 1);
        const id = path[k];
        const ix = id % GW;
        const iy = (id - ix) / GW;
        chosenX = OX + (ix + 0.5) * CELL;
        chosenY = OY + (iy + 0.5) * CELL;
      }

      if (chosenX !== null &&
          Math.hypot(chosenX - x, chosenY - y) > 0.14) {
        desiredX = chosenX;
        desiredY = chosenY;
      }
    }

    if (distT < 4.0 && lineClear(x, y, tx, ty, 4)) {
      desiredX = tx;
      desiredY = ty;
    }

    let desiredHeading = Math.atan2(desiredY - y, desiredX - x);
    if (!isFinite(desiredHeading)) desiredHeading = heading;
    const err = wrap(desiredHeading - heading);
    const absErr = Math.abs(err);

    const front = rays[2];
    const leftNear = Math.min(rays[3], rays[4]);
    const rightNear = Math.min(rays[1], rays[0]);
    const sideMin = Math.min(rays[0], rays[1], rays[3], rays[4]);

    let avoid = 0;

    for (let i = 0; i < 5; i++) {
      if (i === 2) continue;
      const r = rays[i];
      const rel = RAY_ANG[i];
      const safe = (i === 1 || i === 3) ? 0.68 : 0.52;
      if (r < safe) {
        let c = (safe - r) / safe;
        if (c > 1) c = 1;
        const w = (i === 1 || i === 3) ? 0.65 : 0.45;
        avoid -= (rel > 0 ? 1 : -1) * c * c * w;
      }
    }

    if (front < 1.00) {
      const diff = leftNear - rightNear;
      let side = clamp(diff / 0.75, -1, 1);
      if (Math.abs(diff) < 0.10) {
        side = Math.abs(err) > 0.10 ? (err > 0 ? 1 : -1) : (Number(mem.avoidSide) || 1);
      }
      const urg = (1.00 - front) / 1.00;
      avoid += side * urg * urg * 0.90;
      if (front < 0.62) mem.avoidSide = side;
    }

    avoid = clamp(avoid, -1.0, 1.0);
    const alpha = front < 0.62 ? 0.65 : 0.25;
    mem.avoidFilter = (Number(mem.avoidFilter) || 0) * (1 - alpha) + avoid * alpha;
    let steerAvoid = front < 0.52 ? avoid : (Number(mem.avoidFilter) || 0);
    steerAvoid = clamp(steerAvoid, -0.90, 0.90);

    const yawUse = clamp(Number(mem.yawFilter) || 0, -2.8, 2.8);
    let turn = 0.34 * err - 0.26 * yawUse + 0.62 * steerAvoid;

    let maxTurn = 0.28;
    if (front < 0.80 || absErr > 1.0) maxTurn = 0.33;
    if (front > 1.30 && absErr < 0.35) maxTurn = 0.27;
    turn = clamp(turn, -maxTurn, maxTurn);

    let desiredV = 0;

    if (front > 0.48) {
      let base = 0.42;

      if (front > 2.35 && sideMin > 0.85 && absErr < 0.20) base = 0.78;
      else if (front > 1.55 && sideMin > 0.68 && absErr < 0.40) base = 0.63;
      else if (front > 1.00 && sideMin > 0.52 && absErr < 0.65) base = 0.50;
      else if (front > 0.74) base = 0.38;

      const errScale = clamp(1.05 - 0.65 * absErr, 0.18, 1);
      desiredV = base * errScale;

      if (absErr > 0.50) desiredV = Math.min(desiredV, 0.46);
      if (absErr > 0.90) desiredV = Math.min(desiredV, 0.27);
      if (absErr > 1.30) desiredV = Math.min(desiredV, 0.12);
      if (absErr > 1.70) desiredV = Math.min(desiredV, 0.05);
    }

    if (Math.abs(turn) > 0.16) desiredV = Math.min(desiredV, 0.54);
    if (Math.abs(turn) > 0.25) desiredV = Math.min(desiredV, 0.37);
    if (Math.abs(turn) > 0.32) desiredV = Math.min(desiredV, 0.24);

    if (front < 1.70) {
      desiredV = Math.min(desiredV, Math.max(0, (front - 0.42) * 1.10));
    }

    const stopMargin = 0.34 + 0.40 * speed;
    if (front < stopMargin && speed > 0.05) desiredV = Math.min(desiredV, -0.03);
    if (front < 0.42) desiredV = Math.min(desiredV, -0.07);
    if (front < 0.28) desiredV = Math.min(desiredV, -0.13);

    if (sideMin < 0.52) desiredV = Math.min(desiredV, 0.42);
    if (sideMin < 0.36) desiredV = Math.min(desiredV, 0.22);
    if (sideMin < 0.24) desiredV = Math.min(desiredV, 0.06);

    const lookOccDist = 0.65 + 0.30 * speed;
    const aheadOcc = occAtWorld(x + Math.cos(heading) * lookOccDist,
                                y + Math.sin(heading) * lookOccDist);
    if (aheadOcc >= 12) desiredV = Math.min(desiredV, 0.32);
    if (aheadOcc >= 20) desiredV = Math.min(desiredV, 0.10);

    if (distT < 2.0) desiredV = Math.min(desiredV, 0.55);
    if (distT < 1.15) desiredV = Math.min(desiredV, 0.40);
    if (distT < 0.80) desiredV = Math.min(desiredV, 0.26);

    left = desiredV - turn;
    right = desiredV + turn;

    const bias = clamp(Number(mem.bias) || 0, -0.06, 0.06);
    if (Math.abs(desiredV) > 0.03 || Math.abs(turn) > 0.03) {
      left += bias;
      right -= bias;
    }

    const m = Math.max(Math.abs(left), Math.abs(right), 1);
    if (m > 1) {
      left /= m;
      right /= m;
    }

    function deadzone(v) {
      if (v > 0.018 && v < 0.11) return 0.11;
      if (v < -0.018 && v > -0.11) return -0.11;
      return v;
    }
    left = deadzone(left);
    right = deadzone(right);

    maxStep = 0.12;
    if (front > 1.40 && sideMin > 0.75 && absErr < 0.45) maxStep = 0.15;
    if (front < 0.72) maxStep = 0.10;
    if (absErr > 1.35 && front > 0.65) maxStep = 0.13;
  }

  const prevL = Number(mem.lastLeft) || 0;
  const prevR = Number(mem.lastRight) || 0;

  left = prevL + clamp(left - prevL, -maxStep, maxStep);
  right = prevR + clamp(right - prevR, -maxStep, maxStep);

  if (rays[2] < 0.32) {
    const avg = (left + right) * 0.5;
    if (avg > 0.02) {
      left -= avg;
      right -= avg;
    }
  }

  if (rays[4] < 0.24 && right > left) {
    const avg = (left + right) * 0.5;
    left = avg;
    right = avg;
  }
  if (rays[0] < 0.24 && left > right) {
    const avg = (left + right) * 0.5;
    left = avg;
    right = avg;
  }

  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);

  if (!inRecovery &&
      speed > 0.15 &&
      Math.abs(lastTurn) < 0.045 &&
      Math.abs(lastDrive) > 0.12 &&
      Math.abs(Number(mem.yawFilter) || 0) < 0.9) {
    mem.bias = clamp(
      (Number(mem.bias) || 0) + (Number(mem.yawFilter) || 0) * dt * 0.010,
      -0.06,
      0.06
    );
  }

  mem.lastT = now;
  mem.lastX = x;
  mem.lastY = y;
  mem.lastRawHeading = hRaw;
  mem.lastLeft = left;
  mem.lastRight = right;
  mem.lastDrive = (left + right) * 0.5;
  mem.lastTurnCmd = (right - left) * 0.5;
  mem.lastTargetIndex = targetIndex;
  mem.lastTx = tx;
  mem.lastTy = ty;

  return { left: left, right: right };
}

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

function act(obs, mem) {
  const t = obs.t;
  if (!mem.init) {
    mem.init = true;
    mem.off = 0;          // compass offset estimated from GPS motion
    mem.hist = [];
    mem.px = obs.x;
    mem.py = obs.y;
    mem.esc = null;
    mem.lastFwd = 0;
    mem.stuckCount = 0;
  }

  // --- heading calibration: compare GPS motion direction with compass ---
  const dx = obs.x - mem.px, dy = obs.y - mem.py;
  const moved = Math.hypot(dx, dy);
  if (moved > 0.3) {
    let gh = Math.atan2(dy, dx) * 180 / Math.PI;
    if (obs.speed < 0) gh += 180;
    if (Math.abs(obs.speed) > 0.1) {
      const diff = wrap(gh - (obs.heading + mem.off));
      mem.off = wrap(mem.off + 0.1 * diff);
    }
    mem.px = obs.x;
    mem.py = obs.y;
  }
  const hd = wrap(obs.heading + mem.off);

  const rays = obs.rays;
  const d = [0, 1, 2, 3, 4].map(i => clamp(rays[i], 0.05, 10));

  // --- stuck detection and escape ---
  mem.hist.push({ t: t, x: obs.x, y: obs.y });
  if (mem.hist.length > 60) mem.hist.shift();
  if (!mem.esc && mem.hist.length >= 40 && mem.lastFwd > 0.25) {
    const h0 = mem.hist[mem.hist.length - 40];
    if (Math.hypot(obs.x - h0.x, obs.y - h0.y) < 0.2) {
      const L = d[3] + d[4], Rs = d[0] + d[1];
      mem.esc = { start: t, dir: L > Rs ? 1 : -1 };  // +1 = turn left
      mem.hist = [];
      mem.stuckCount++;
    }
  }
  if (mem.esc) {
    const el = t - mem.esc.start, s = mem.esc.dir;
    mem.lastFwd = 0;
    if (el < 0.5) return { left: -0.25, right: -0.25 };      // short reverse
    if (el < 2.0) return { left: -0.6 * s, right: 0.6 * s };  // pivot toward open side
    mem.esc = null;
    mem.hist = [];
  }

  // --- steering toward the next checkpoint / flag ---
  const tx = obs.targetX, ty = obs.targetY;
  const bearing = Math.atan2(ty - obs.y, tx - obs.x) * 180 / Math.PI;
  const err = wrap(bearing - hd);

  // --- obstacle repulsion from side rays ---
  const R = 3.0;
  const pushL = Math.max(0, R - d[3]) / R + Math.max(0, R - d[4]) / R; // left side
  const pushR = Math.max(0, R - d[0]) / R + Math.max(0, R - d[1]) / R; // right side
  const front = d[2];
  const avoid = (pushR - pushL) * 1.0;                   // positive turns left
  let side = pushR !== pushL ? Math.sign(pushR - pushL) : (err >= 0 ? 1 : -1);

  let turn = clamp(0.025 * err, -1, 1) + avoid;
  if (front < R) {
    const c = (R - front) / R;
    turn += c * side * 1.5;
  }

  let v = 0.7 * clamp((front - 0.6) / 2.5, 0, 1) * clamp(1 - Math.abs(err) / 90, 0.2, 1);
  if (front < 0.7) {
    v = 0;
    turn = 0.7 * side;   // pivot away from the blocked front
  }
  turn = clamp(turn, -1, 1);

  mem.lastFwd = v;
  const left = clamp(v - turn, -1, 1);
  const right = clamp(v + turn, -1, 1);
  return { left: left, right: right };
}

const ANG = [-60, -30, 0, 30, 60];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

// clearance (m) in a direction th (deg, positive = left) relative to heading
function clr(d, th) {
  if (th <= -60) return d[0] * (th < -60 ? 0.7 : 1);
  if (th >= 60) return d[4] * (th > 60 ? 0.7 : 1);
  for (let i = 0; i < 4; i++) {
    if (th >= ANG[i] && th <= ANG[i + 1]) {
      const f = (th - ANG[i]) / (ANG[i + 1] - ANG[i]);
      return d[i] + f * (d[i + 1] - d[i]);
    }
  }
  return d[2];
}

function act(obs, mem) {
  const t = obs.t;
  if (!mem.init) {
    mem.init = true;
    mem.off = 0;            // compass offset, slowly corrected from GPS motion
    mem.ax = obs.x; mem.ay = obs.y;   // anchor for displacement-based heading
    mem.hist = [];
    mem.esc = null;
    mem.escCool = 0;
    mem.prevTh = 0;
    mem.lastV = 0;
  }

  // ---- heading correction from GPS displacement over >= 0.8 m ----
  const dA = Math.hypot(obs.x - mem.ax, obs.y - mem.ay);
  if (dA >= 0.8) {
    let gh = Math.atan2(obs.y - mem.ay, obs.x - mem.ax) * 180 / Math.PI;
    if (obs.speed < 0) gh += 180;
    if (Math.abs(obs.speed) > 0.15) {
      const diff = wrap(gh - (obs.heading + mem.off));
      mem.off = wrap(mem.off + 0.3 * diff);
    }
    mem.ax = obs.x; mem.ay = obs.y;
  }
  const hd = wrap(obs.heading + mem.off);

  const d = [0, 1, 2, 3, 4].map(i => clamp(obs.rays[i], 0.05, 10));

  // ---- stuck detection over ~3 s ----
  mem.hist.push({ t: t, x: obs.x, y: obs.y });
  if (mem.hist.length > 60) mem.hist.shift();
  if (!mem.esc && t > mem.escCool && mem.hist.length >= 60 && mem.lastV > 0.2) {
    const h0 = mem.hist[0];
    if (Math.hypot(obs.x - h0.x, obs.y - h0.y) < 0.35) {
      const L = d[3] + d[4], R = d[0] + d[1];
      mem.esc = { start: t, dir: L > R ? 1 : -1 };
      mem.hist = [];
    }
  }
  if (mem.esc) {
    const el = t - mem.esc.start, s = mem.esc.dir;
    mem.lastV = 0;
    if (el < 1.0) return { left: -0.5, right: -0.5 };
    if (el < 2.2) return { left: -0.7 * s, right: 0.7 * s };
    mem.esc = null;
    mem.escCool = t + 2.0;
    mem.hist = [];
  }

  // ---- steering: pick free direction nearest to target bearing ----
  const bearing = Math.atan2(obs.targetY - obs.y, obs.targetX - obs.x) * 180 / Math.PI;
  const err = wrap(bearing - hd);
  const S = 1.5; // wanted clearance in metres

  let best = 0, bestCost = Infinity, bestC = 0;
  for (let th = -90; th <= 90; th += 5) {
    const c = clr(d, th);
    let cost = Math.abs(th - err) + 120 * Math.max(0, S - c);
    // hysteresis: avoid flipping turn side
    if (Math.abs(mem.prevTh) > 15 && Math.sign(th) !== Math.sign(mem.prevTh)) cost += 20;
    if (cost < bestCost) { bestCost = cost; best = th; bestC = c; }
  }
  mem.prevTh = best;

  const rad = best * Math.PI / 180;
  let w = clamp(rad * 1.2, -0.9, 0.9);
  let v = 0.8 * clamp((bestC - 0.7) / 2.0, 0, 1) * clamp(Math.cos(rad), 0, 1);
  if (Math.abs(best) > 50) v = 0;
  if (v > 0 && v < 0.3) v = 0.3;

  if (v === 0 && Math.abs(w) < 0.5) {
    const s = (d[3] + d[4] > d[0] + d[1]) ? 1 : -1;
    w = 0.6 * s;
  }

  mem.lastV = v;
  return {
    left: clamp(v - w, -1, 1),
    right: clamp(v + w, -1, 1)
  };
}

const ANG = [-60, -30, 0, 30, 60];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

// clearance (m) in direction th (deg, positive = left) relative to heading
function clr(d, th) {
  if (th <= -60) return d[0];
  if (th >= 60) return d[4];
  for (let i = 0; i < 4; i++) {
    if (th >= ANG[i] && th <= ANG[i + 1]) {
      const f = (th - ANG[i]) / 30;
      return d[i] + f * (d[i + 1] - d[i]);
    }
  }
  return d[2];
}

function act(obs, mem) {
  const t = obs.t;
  if (!mem.init) {
    mem.init = true;
    mem.off = 0;                       // compass offset, calibrated from GPS motion
    mem.ax = obs.x; mem.ay = obs.y;    // anchor for straight-line displacement
    mem.hdF = null;                    // filtered heading
    mem.prevRaw = null;
    mem.hist = [];
    mem.visits = {};
    mem.cell = '';
    mem.esc = null;
    mem.escCool = -1;
    mem.pivotSign = 0;
    mem.prevBest = 0;
    mem.lastV = 0;
    mem.zeroSince = -1;
    mem.lastCmd = { l: 0, r: 0 };
  }
  const out = (L, R) => {
    L = clamp(L, -1, 1); R = clamp(R, -1, 1);
    mem.lastCmd = { l: L, r: R };
    return { left: L, right: R };
  };

  // ---- rays: min over current and previous tick (conservative vs. missed returns) ----
  const raw = [0, 1, 2, 3, 4].map(i => clamp(obs.rays[i], 0.05, 10));
  const d = mem.prevRaw ? raw.map((v, i) => Math.min(v, mem.prevRaw[i])) : raw.slice();
  mem.prevRaw = raw;

  // ---- heading calibration: compare GPS displacement with compass during straight driving ----
  const cmd = mem.lastCmd;
  const straight = cmd.l > 0.2 && cmd.r > 0.2 && Math.abs(cmd.l - cmd.r) < 0.3;
  if (!straight) {
    mem.ax = obs.x; mem.ay = obs.y;
  } else if (Math.hypot(obs.x - mem.ax, obs.y - mem.ay) >= 1.0) {
    if (obs.speed > 0.2) {
      const gh = Math.atan2(obs.y - mem.ay, obs.x - mem.ax) * 180 / Math.PI;
      mem.off = wrap(mem.off + 0.25 * wrap(gh - (obs.heading + mem.off)));
    }
    mem.ax = obs.x; mem.ay = obs.y;
  }
  const hdRaw = wrap(obs.heading + mem.off);
  if (mem.hdF === null) mem.hdF = hdRaw;
  else mem.hdF = wrap(mem.hdF + 0.6 * wrap(hdRaw - mem.hdF));
  const hd = mem.hdF;

  // ---- visit counting on 1 m grid ----
  const cellKey = Math.floor(obs.x) + ',' + Math.floor(obs.y);
  if (cellKey !== mem.cell) {
    mem.cell = cellKey;
    mem.visits[cellKey] = (mem.visits[cellKey] || 0) + 1;
  }

  // ---- stuck detection ----
  mem.hist.push({ x: obs.x, y: obs.y });
  if (mem.hist.length > 60) mem.hist.shift();
  const startEsc = () => {
    mem.esc = {
      t0: t,
      phase: d[2] < 0.8 ? 0 : 1,
      s: (d[3] + d[4] > d[0] + d[1]) ? 1 : -1
    };
    mem.hist = [];
    mem.zeroSince = -1;
  };
  if (!mem.esc && t > mem.escCool && mem.hist.length >= 60 && mem.lastV > 0.2) {
    const h0 = mem.hist[0];
    if (Math.hypot(obs.x - h0.x, obs.y - h0.y) < 0.3) startEsc();
  }
  if (!mem.esc && t > mem.escCool && mem.zeroSince >= 0 && t - mem.zeroSince > 5) startEsc();

  // ---- escape: optional short reverse, then pivot toward the more open side ----
  if (mem.esc) {
    const e = mem.esc;
    if (e.phase === 0) {
      if (t - e.t0 < 0.5) { mem.lastV = 0; return out(-0.3, -0.3); }
      e.phase = 1; e.t0 = t;
    }
    if (t - e.t0 < 1.5) { mem.lastV = 0; return out(-0.6 * e.s, 0.6 * e.s); }
    mem.esc = null;
    mem.escCool = t + 2;
    mem.hist = [];
    mem.pivotSign = 0;
    mem.zeroSince = -1;
  }

  // ---- steering target ----
  const tx = obs.targetX, ty = obs.targetY;
  const dist = Math.hypot(tx - obs.x, ty - obs.y);
  const bearing = Math.atan2(ty - obs.y, tx - obs.x) * 180 / Math.PI;
