    cost += 80 * Math.max(0, S - c);
    if (lx < 2.5 || lx > 37.5 || ly < 2.5 || ly > 37.5) cost += 60;
    const n = mem.visits[Math.floor(lx) + ',' + Math.floor(ly)] || 0;
    cost += 4 * Math.min(Math.max(0, n - 1), 6);
    if (Math.abs(mem.prevBest) > 10 && Math.sign(th) !== Math.sign(mem.prevBest)) cost += 20;
    if (cost < bestCost) { bestCost = cost; best = th; }
  }
