  const cf = clr(d, best);
  let turn = clamp(0.025 * best, -0.9, 0.9);
  let v = 0.7 * clamp((cf - 0.6) / 1.8, 0, 1) * clamp(1 - Math.abs(best) / 70, 0, 1);
  if (dist < 1.5) v *= 0.6;
  if (Math.abs(best) >= 60) v = 0;
  if (v > 0 && v < 0.25) v = 0.25;

