    if (mem.pivotSign === 0) {
      mem.pivotSign = turn !== 0 ? Math.sign(turn) : (d[3] + d[4] > d[0] + d[1] ? 1 : -1);
    }
    turn = mem.pivotSign * Math.max(0.45, Math.abs(turn));
  } else {
    mem.pivotSign = 0;
  }

  mem.lastV = v;
  if (v === 0) { if (mem.zeroSince < 0) mem.zeroSince = t; }
  else mem.zeroSince = -1;

  return out(v - turn, v + turn);
}

const N = 80, CS = 0.5, VMAX = 0.7;
const ANG = [-60, -30, 0, 30, 60];
const DX8 = [1, -1, 0, 0, 1, 1, -1, -1], DY8 = [0, 0, 1, -1, 1, -1, 1, -1];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

function cellIdx(x, y) {
  let cx = Math.floor(x / CS), cy = Math.floor(y / CS);
  cx = clamp(cx, 0, N - 1); cy = clamp(cy, 0, N - 1);
  return cy * N + cx;
}

function markCell(mem, x, y, delta) {
  const cx = Math.floor(x / CS), cy = Math.floor(y / CS);
  if (cx < 0 || cy < 0 || cx >= N || cy >= N) return;
  const i = cy * N + cx;
  mem.L[i] = clamp(mem.L[i] + delta, -3, 3);
