// integrate five range readings into the log-odds grid
function rayUpdate(mem, x, y, hd, rays) {
  for (let k = 0; k < 5; k++) {
    const r = rays[k];
    const a = (hd + ANG[k]) * Math.PI / 180;
    const c = Math.cos(a), s = Math.sin(a);
    const hit = r < 9.8;
    const reach = hit ? r - 0.3 : 9.8;
    for (let st = 0.25; st < reach; st += 0.25) {
      markCell(mem, x + c * st, y + s * st, -0.35);
    }
    if (hit) markCell(mem, x + c * r, y + s * r, 1.0);
  }
}

// blocked = inflated obstacle or arena margin; near = penalty zone
function buildMasks(mem) {
  const n = N * N;
  const blk = new Uint8Array(n), near = new Uint8Array(n);
  for (let cy = 0; cy < N; cy++) {
    for (let cx = 0; cx < N; cx++) {
      const i = cy * N + cx;
      const x = (cx + 0.5) * CS, y = (cy + 0.5) * CS;
      if (x < 0.6 || x > 39.4 || y < 0.6 || y > 39.4) blk[i] = 1;
      if (x < 1.1 || x > 38.9 || y < 1.1 || y > 38.9) near[i] = 1;
    }
  }
  for (let cy = 0; cy < N; cy++) {
    for (let cx = 0; cx < N; cx++) {
      const i = cy * N + cx;
      if (mem.L[i] <= 0.5) continue;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          const nx = cx + dx, ny = cy + dy;
          if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
          const j = ny * N + nx;
          near[j] = 1;
          if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1) blk[j] = 1;
        }
      }
    }
  }
  return { blk, near };
}

// A* on the grid; unknown cells are passable but cost a little more
function astar(mem, blk, near, s, g) {
  const n = N * N;
  const gs = new Float32Array(n).fill(1e9);
  const par = new Int32Array(n).fill(-1);
  const cl = new Uint8Array(n);
  const gx = g % N, gy = (g / N) | 0;
  const hfun = (i) => {
    const dx = Math.abs((i % N) - gx), dy = Math.abs(((i / N) | 0) - gy);
    return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
  };
  const hk = [], hv = [];
  const push = (k, v) => {
    hk.push(k); hv.push(v);
    let c = hk.length - 1;
    while (c > 0) {
      const p = (c - 1) >> 1;
      if (hk[p] <= hk[c]) break;
      let tk = hk[p]; hk[p] = hk[c]; hk[c] = tk;
      let tv = hv[p]; hv[p] = hv[c]; hv[c] = tv;
      c = p;
    }
  };
  const pop = () => {
    const topV = hv[0];
    const lk = hk.pop(), lv = hv.pop();
    if (hk.length > 0) {
      hk[0] = lk; hv[0] = lv;
      let p = 0;
      for (;;) {
        const l = 2 * p + 1, r = l + 1;
        let m = p;
        if (l < hk.length && hk[l] < hk[m]) m = l;
        if (r < hk.length && hk[r] < hk[m]) m = r;
        if (m === p) break;
        let tk = hk[m]; hk[m] = hk[p]; hk[p] = tk;
        let tv = hv[m]; hv[m] = hv[p]; hv[p] = tv;
        p = m;
      }
    }
    return topV;
  };
  gs[s] = 0;
  push(hfun(s), s);
  while (hk.length > 0) {
    const i = pop();
    if (cl[i]) continue;
    if (i === g) break;
    cl[i] = 1;
    const cx = i % N, cy = (i / N) | 0;
    for (let k = 0; k < 8; k++) {
      const nx = cx + DX8[k], ny = cy + DY8[k];
      if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
      const j = ny * N + nx;
      if (cl[j]) continue;
      if (blk[j] && j !== g) continue;
      const diag = k >= 4;
      if (diag && (blk[cy * N + nx] || blk[ny * N + cx])) continue;
      const step = diag ? 1.414 : 1;
      const c = step * (1 + (near[j] ? 1.5 : 0) + (mem.L[j] === 0 ? 0.4 : 0));
      const ng = gs[i] + c;
      if (ng < gs[j]) {
        gs[j] = ng;
        par[j] = i;
        push(ng + hfun(j), j);
      }
    }
  }
