  const dc = wrap(obs.heading - mem.prevCompass);
  mem.prevCompass = obs.heading;
  mem.rate = 0.7 * mem.rate + 0.3 * (dc / DT);

  // ---- map update ----
  rayUpdate(mem, obs.x, obs.y, hd, rays);

  // ---- stuck detection: no 0.4 m progress for 5 s ----
  if (Math.hypot(obs.x - mem.anX, obs.y - mem.anY) > 0.4) {
    mem.anX = obs.x; mem.anY = obs.y; mem.anT = t;
