          const nx = cx + dx, ny = cy + dy;
          if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
          const j = ny * N + nx;
          near[j] = 1;
          if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1) blk[j] = 1;
