    cl[i] = 1;
    const cx = i % N, cy = (i / N) | 0;
    for (let k = 0; k < 8; k++) {
      const nx = cx + DX8[k], ny = cy + DY8[k];
      if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
      const j = ny * N + nx;
      if (cl[j]) continue;
      if (blk[j] && j !== g) continue;
      const diag = k >= 4;
      if (diag && (blk[cy * N + nx] || blk[ny * N + cx])) continue;
      const step = diag ? 1.414 : 1;
      const c = step * (1 + (near[j] ? 1.5 : 0) + (mem.L[j] === 0 ? 0.4 : 0));
      const ng = gs[i] + c;
      if (ng < gs[j]) { gs[j] = ng; par[j] = i; push(ng + hf(j), j); }
    }
  }
  if (gs[g] >= 1e8) return null;
  const path = [];
  let c = g;
  while (c !== -1) {
    path.push(c);
    if (c === s) break;
    c = par[c];
  }
  path.reverse();
  return path;
}

// straight segment through the inflated obstacle grid?
function lineClear(blk, x0, y0, x1, y1) {
  const d = Math.hypot(x1 - x0, y1 - y0);
  const n = Math.max(1, Math.ceil(d / 0.2));
  for (let k = 1; k <= n; k++) {
    const f = k / n;
    const x = x0 + (x1 - x0) * f, y = y0 + (y1 - y0) * f;
    const cx = Math.floor(x / CS), cy = Math.floor(y / CS);
    if (cx < 0 || cy < 0 || cx >= N || cy >= N) return false;
    if (blk[cy * N + cx]) return false;
  }
  return true;
}

function act(obs, mem) {
  const t = obs.t;
  if (!mem.init) {
    mem.init = true;
    mem.L = new Float32Array(N * N);
    mem.blk = new Uint8Array(N * N);
    mem.near = new Uint8Array(N * N);
    mem.off = 0;
    mem.ax = obs.x; mem.ay = obs.y;
    mem.hdF = null;
    mem.path = [];
    mem.tgt = -2;
    mem.tick = 0;
    mem.lastPlan = -100;
    mem.lastL = 0; mem.lastR = 0;
    mem.anX = obs.x; mem.anY = obs.y; mem.anT = t;
    mem.escUntil = -1; mem.escStart = 0; mem.escS = 1;
    mem.lastEscS = 1; mem.lastEscT = -100;
  }
  mem.tick++;

  const rays = [0, 1, 2, 3, 4].map(i => {
    let r = Number(obs.rays && obs.rays[i]);
    if (!isFinite(r)) r = 10;
    return clamp(r, 0.05, 10);
  });

  // ---- heading: compass + offset calibrated from straight GPS displacement ----
  const straight = mem.lastL > 0.25 && mem.lastR > 0.25 && Math.abs(mem.lastL - mem.lastR) < 0.15;
  if (!straight) {
    mem.ax = obs.x; mem.ay = obs.y;
  } else if (Math.hypot(obs.x - mem.ax, obs.y - mem.ay) >= 1.5) {
    if (obs.speed > 0.15) {
      const gh = Math.atan2(obs.y - mem.ay, obs.x - mem.ax) * 180 / Math.PI;
      mem.off = wrap(mem.off + 0.15 * wrap(gh - (obs.heading + mem.off)));
    }
    mem.ax = obs.x; mem.ay = obs.y;
  }
  const raw = wrap(obs.heading + mem.off);
  mem.hdF = mem.hdF === null ? raw : wrap(mem.hdF + 0.5 * wrap(raw - mem.hdF));
  const hd = mem.hdF;

  // ---- map update ----
  rayUpdate(mem, obs.x, obs.y, hd, rays);

  // ---- stuck detection: no 0.6 m progress for 6 s ----
  if (Math.hypot(obs.x - mem.anX, obs.y - mem.anY) > 0.6) {
    mem.anX = obs.x; mem.anY = obs.y; mem.anT = t;
  }
  if (t >= mem.escUntil && t - mem.anT > 6) {
    let s = (rays[3] + rays[4] > rays[0] + rays[1]) ? 1 : -1;
    if (t - mem.lastEscT < 12) s = -mem.lastEscS;
    mem.escS = s; mem.lastEscS = s; mem.lastEscT = t;
    mem.escStart = t; mem.escUntil = t + 2.0;
    mem.anT = t; mem.path = [];
    const cx = Math.floor(obs.x / CS), cy = Math.floor(obs.y / CS);
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        const nx = cx + dx, ny = cy + dy;
        if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
        const i = ny * N + nx;
        if (mem.L[i] > 0) mem.L[i] = 0;
      }
    }
  }
  if (t < mem.escUntil) {
    const el = t - mem.escStart;
    let L, R;
    if (el < 0.8) { L = -0.4; R = -0.4; }
    else { L = -0.5 * mem.escS; R = 0.5 * mem.escS; }
    mem.lastL = L; mem.lastR = R;
    return { left: L, right: R };
  }

  // ---- replan: on target change, every 6 ticks, or when path is missing ----
  const tgtIdx = obs.targetIndex;
  if (tgtIdx !== mem.tgt || mem.tick - mem.lastPlan >= 6 || (mem.path.length < 2 && mem.tick - mem.lastPlan >= 3)) {
    mem.tgt = tgtIdx;
    mem.lastPlan = mem.tick;
    const m = buildMasks(mem);
    mem.blk = m.blk; mem.near = m.near;
    mem.path = astar(mem, m.blk, m.near, cellIdx(obs.x, obs.y), cellIdx(obs.targetX, obs.targetY)) || [];
  }

  // ---- aim point: direct to target if line clear, else string-pulled path point ----
  const tdist = Math.hypot(obs.targetX - obs.x, obs.targetY - obs.y);
  let aimX = obs.targetX, aimY = obs.targetY;
  const P = mem.path;
  if (!lineClear(mem.blk, obs.x, obs.y, obs.targetX, obs.targetY) && P.length > 1) {
    let best = -1, firstFar = -1;
    for (let k = 1; k < P.length; k++) {
      const c = P[k];
      const wx = ((c % N) + 0.5) * CS, wy = (((c / N) | 0) + 0.5) * CS;
      const d = Math.hypot(wx - obs.x, wy - obs.y);
      if (firstFar < 0 && d >= 1.0) firstFar = k;
      if (d > 4.0) break;
      if (d < 0.8) continue;
      if (!lineClear(mem.blk, obs.x, obs.y, wx, wy)) break;
      best = k;
    }
    const pick = best >= 0 ? best : firstFar;
    if (pick >= 0) {
      const c = P[pick];
      aimX = ((c % N) + 0.5) * CS; aimY = (((c / N) | 0) + 0.5) * CS;
    }
  }

  // ---- steering: low-gain proportional heading control (plant pivots fast, with lag) ----
  const des = Math.atan2(aimY - obs.y, aimX - obs.x) * 180 / Math.PI;
  const e = wrap(des - hd);
  const ae = Math.abs(e);

  let w = clamp(0.004 * e, -0.5, 0.5);
  if (ae > 5 && Math.abs(w) < 0.12) w = 0.12 * Math.sign(e);

  // gentle side repulsion (positive w = turn left / CCW)
  const leftMin = Math.min(rays[3], rays[4]);
  const rightMin = Math.min(rays[0], rays[1]);
  w += 0.2 * clamp((0.9 - rightMin) / 0.5, 0, 1);
  w -= 0.2 * clamp((0.9 - leftMin) / 0.5, 0, 1);
  // when something is close ahead, bias the pivot toward the more open side
  if (rays[2] < 0.8) w += 0.2 * Math.sign(leftMin - rightMin);
  w = clamp(w, -0.6, 0.6);

  // ---- forward speed: mostly independent of small heading error ----
  const fa = clamp(1 - ae / 60, 0, 1);
  const fc = clamp((rays[2] - 0.4) / 1.6, 0, 1);
  const fs = clamp((Math.min(leftMin, rightMin) - 0.35) / 0.8, 0, 1);
  let v = VMAX * fa * fc * (0.4 + 0.6 * fs);
  if (ae > 70) v = 0;
  if (v > 0 && v < 0.18 && ae < 45) v = 0.18;
  if (tdist < 1.5) v *= 0.7;

  const L = clamp(v - w, -1, 1), R = clamp(v + w, -1, 1);
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R };
}

const N = 80, CS = 0.5, VMAX = 0.75, DT = 0.05;
const ANG = [-60, -30, 0, 30, 60];
const DX8 = [1, -1, 0, 0, 1, 1, -1, -1], DY8 = [0, 0, 1, -1, 1, -1, 1, -1];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

function cellIdx(x, y) {
  const cx = clamp(Math.floor(x / CS), 0, N - 1), cy = clamp(Math.floor(y / CS), 0, N - 1);
  return cy * N + cx;
}

function markCell(mem, x, y, delta) {
  const cx = Math.floor(x / CS), cy = Math.floor(y / CS);
  if (cx < 0 || cy < 0 || cx >= N || cy >= N) return;
  const i = cy * N + cx;
  mem.L[i] = clamp(mem.L[i] + delta, -3, 3);
}

function rayUpdate(mem, x, y, hd, rays) {
  for (let k = 0; k < 5; k++) {
    const r = rays[k];
    const a = (hd + ANG[k]) * Math.PI / 180;
    const c = Math.cos(a), s = Math.sin(a);
    const hit = r < 9.5;
    const reach = hit ? Math.max(0, r - 0.3) : 9.5;
    for (let st = 0.25; st < reach; st += 0.25) markCell(mem, x + c * st, y + s * st, -0.3);
    if (hit) markCell(mem, x + c * r, y + s * r, 1.0);
  }
}

function buildMasks(mem) {
  const n = N * N;
  const blk = new Uint8Array(n), near = new Uint8Array(n);
  for (let cy = 0; cy < N; cy++) {
    for (let cx = 0; cx < N; cx++) {
      const i = cy * N + cx, x = (cx + 0.5) * CS, y = (cy + 0.5) * CS;
      if (x < 0.8 || x > 39.2 || y < 0.8 || y > 39.2) blk[i] = 1;
      else if (x < 1.5 || x > 38.5 || y < 1.5 || y > 38.5) near[i] = 1;
    }
  }
  for (let cy = 0; cy < N; cy++) {
    for (let cx = 0; cx < N; cx++) {
      const i = cy * N + cx;
      if (mem.L[i] <= 0.5) continue;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          const nx = cx + dx, ny = cy + dy;
          if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
          const j = ny * N + nx;
          near[j] = 1;
          if (Math.abs(dx) <= 1 && Math.abs(dy) <= 1) blk[j] = 1;
        }
      }
    }
  }
  return { blk, near };
}

function astar(mem, blk, near, s, g) {
  const n = N * N;
  const gs = new Float32Array(n).fill(1e9);
  const par = new Int32Array(n).fill(-1);
  const cl = new Uint8Array(n);
  const gx = g % N, gy = (g / N) | 0;
  const hf = (i) => {
    const dx = Math.abs((i % N) - gx), dy = Math.abs(((i / N) | 0) - gy);
    return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
  };
  const hk = [], hv = [];
  const push = (k, v) => {
    hk.push(k); hv.push(v);
    let c = hk.length - 1;
    while (c > 0) {
      const p = (c - 1) >> 1;
      if (hk[p] <= hk[c]) break;
      let tk = hk[p]; hk[p] = hk[c]; hk[c] = tk;
      let tv = hv[p]; hv[p] = hv[c]; hv[c] = tv;
      c = p;
    }
  };
  const pop = () => {
    const top = hv[0];
    const lk = hk.pop(), lv = hv.pop();
    if (hk.length > 0) {
      hk[0] = lk; hv[0] = lv;
      let p = 0;
      for (;;) {
        const l = 2 * p + 1, r = l + 1;
        let m = p;
        if (l < hk.length && hk[l] < hk[m]) m = l;
        if (r < hk.length && hk[r] < hk[m]) m = r;
        if (m === p) break;
        let tk = hk[m]; hk[m] = hk[p]; hk[p] = tk;
        let tv = hv[m]; hv[m] = hv[p]; hv[p] = tv;
        p = m;
      }
    }
    return top;
  };
  gs[s] = 0;
  push(hf(s), s);
  while (hk.length > 0) {
    const i = pop();
    if (cl[i]) continue;
    if (i === g) break;
    cl[i] = 1;
    const cx = i % N, cy = (i / N) | 0;
    for (let k = 0; k < 8; k++) {
      const nx = cx + DX8[k], ny = cy + DY8[k];
      if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
      const j = ny * N + nx;
      if (cl[j]) continue;
      if (blk[j] && j !== g) continue;
      const diag = k >= 4;
      if (diag && (blk[cy * N + nx] || blk[ny * N + cx])) continue;
      const step = diag ? 1.414 : 1;
      const c = step * (1 + (near[j] ? 1.5 : 0) + (mem.L[j] === 0 ? 0.4 : 0));
      const ng = gs[i] + c;
      if (ng < gs[j]) { gs[j] = ng; par[j] = i; push(ng + hf(j), j); }
    }
  }
  if (gs[g] >= 1e8) return null;
  const path = [];
  let c = g;
  while (c !== -1) {
    path.push(c);
    if (c === s) break;
    c = par[c];
  }
  path.reverse();
  return path;
}

